$string['settings:rag_chunksize'] = 'Dayoy chunk bi (baat)';
$string['settings:rag_chunksize_desc'] = 'Limu baat yi ñu jublu ci chunk bu nekk bu lu nekk ci njàng bi bu ñuy indexe. Chunk yu ndaw ñoo gën a wóor; chunk yu mag dañuy jox lu ëpp ngir xam mbir mi.';
$string['settings:rag_return_scope'] = 'Wàll wu delloo ci retrieval bi';
$string['settings:rag_return_scope_desc'] = 'Lu ñuy dugal ci saa su ñu retrieve benn bit. "chunk" (default) dafay dugal chunk bi mu jaap, lu mat ci ~400 baat. "window" dafay dugal chunk boobu ak ay chunk yu ci wër ci menn xët. "page" dafay dugal xët bu mat bu module bi mu bokk. window/page dañuy jariñu bu tontu bi tasaare ci lu ëpp benn xët, waaye dafay yokk lu mag ci prompt bi.';
$string['settings:rag_window_size'] = 'Dayo window bi ci retrieval';
$string['settings:rag_window_size_desc'] = 'Ngir etandu delloo "window" bi: limu chunk yu ci wër yu war a bokk ci kaw ak ci suuf chunk bi mu jaap. Default mooy 1.';
$string['settings:rag_parent_max_chars'] = 'Limit bu mag bu passage bu njëkk (karakteer)';
$string['settings:rag_parent_max_chars_desc'] = 'Lim bu mag bu karakteer yi ngir benn window/page passage bu yokk. Xët yu jege limit dañuy dellu ci window, ba noppi ci benn chunk rekk. Default mooy 6000.';
$string['settings:rag_enabled'] = 'Sopp RAG (Wut bu semantik)';
$string['settings:rag_enabled_desc'] = 'Bu ñu ko soppee, jàngalekat AI bi dafay jëfandikoo wut bu semantik ngir jële lu am solo ci njàng bi ci ñaan bu nekk, ci lu dul duggal lépp ci prompt bu sistem bi.';
$string['settings:rag_heading'] = 'RAG / Wut bu semantik';
$string['settings:rag_heading_desc'] = 'Retrieval-Augmented Generation: indexe lu nekk ci njàng bi ni ay embedding, ba noppi jële chunk yi gën a am solo rekk ci saa bu ñaan bi ñëwee. Dafay wàññi jëfandikoo tokens yi te dafay nangu xeeti lu nekk yépp. Dafa soxla benn API embedding.';
