// v4.6.0: vendor DPA gating + override editors.
$string['settings:vendor_data_heading'] = 'Données yu yónent ak njëg';
$string['settings:vendor_data_heading_desc'] = 'Kontrol yu xëtu ndawal bu Vendor DPA bi ñu mën a bàyyi ak editër yu soppi yi di may ndawal yi denc taabalu yónent bi ak taabalu njëg bu LLM bi ci lu yees te duñu soppi kod bi. Ñaari editër yu soppi yi ñépp ci JSON lañu; valeur bu amul dara dafay dellu ci default yi ñu bind ci plugin bi.';
$string['settings:vendor_dpa_admin_page_enabled'] = 'Wone xëtu ndawal bu Vendor DPA';
