$string['emergency:flag_all'] = 'MASTER KILL';
$string['emergency:flag_all_desc'] = 'Dafay faral plugin bi yépp: widget bi dëkk ci xët yi yépp, tâche yi planifié yi tëj, dëggu bi clear, RAG faraloo, outreach faraloo. Switch bu gën a dëgëm — jëfandikool ngir benn incident sécurité walla su war a jaaxal [[tutorshort]] ci saa si.';
$string['emergency:settings_link'] = 'Contrôle yu urgence';
