$string['settings:rag_extract_pdf_desc'] = 'Dafay génne mbind ci dencukaay yu PDF yi ñu yeb ak jumtukaay <code>pdftotext</code> (poppler). Yoonu jumtukaay bi dañu koy gis ci boppam; wone ko ci suuf su soxla.';
$string['settings:rag_pdftotext_path'] = 'Yoonu jumtukaay pdftotext';
$string['settings:rag_pdftotext_path_desc'] = 'Bàyyi ko neen ngir gis ko ci boppam (dañuy seet <code>/usr/bin/pdftotext</code>, <code>/usr/local/bin/pdftotext</code> ak <code>which pdftotext</code>). Fees ko rekk su sa samp bi nekkoon feneen.';
$string['settings:rag_extract_docx'] = 'Limal dencukaay yu DOCX (mod_resource)';
$string['settings:rag_extract_docx_desc'] = 'Dafay génne mbind ci téere yu Word yi ñu yeb ak ZipArchive bu PHP. Amul soxla ci biti.';
$string['settings:rag_extract_pptx'] = 'Limal dencukaay yu PPTX (mod_resource)';
$string['settings:rag_extract_pptx_desc'] = 'Dafay génne mbind ci wonewiin yu PowerPoint yu tey yi ñu yeb ak ZipArchive bu PHP. Dafay jaar ci XML bu xët yi ak notu waxkat bi ci toftalub xët yi; amul soxla ci biti. Dencukaay yu binaari yu jëkk <code>.ppt</code> duñu ko nangu — dencaat wonewiin yooyu ni <code>.pptx</code>.';
$string['settings:rag_extract_h5p'] = 'Limal li nekk ci H5P (mod_h5p)';
$string['settings:rag_extract_h5p_desc'] = 'Dafay jaar ci JSON bu li nekk ci H5P te dafay limal bépp tool bu am mbind (laaj, tontu, feedback, leeral). Xibaaru xeetu li nekk ci H5P yaa ngi yaatu; ci mbir yu bunt, ay dëppoo yu njuumte lañuy séen.';
$string['settings:rag_extract_scorm'] = 'Limal mbooloo yu SCORM (mod_scorm)';
$string['settings:rag_extract_scorm_desc'] = 'Dafay ubbi mbooloo yu SCORM te dafay limal <code>imsmanifest.xml</code>, bépp dencukaay <code>.html</code>, ak baat yu li nekk ci Articulate Storyline. <strong>Tëjul ci mbir mi</strong>, ndax jëfandikoob SCORM mën na jafe lool. Réyaayu mbooloo bi gën a réy <code>rag_scorm_max_mb</code> lay dogal.';
$string['settings:rag_scorm_max_mb'] = 'Réyaayu mbooloo SCORM bi gën a réy ñu koy limal (MB)';
$string['settings:rag_scorm_max_mb_desc'] = 'Dafay teg mbooloo yu SCORM yu gën a réy ci xayma bii ngir moytu jëfandikoo xel bu ëpp.';
$string['settings:rag_fetch_transcripts'] = 'Jël bindu waxin ngir wideyo ak li nekk ci jokkoo yu ñu dugal';
$string['settings:rag_fetch_transcripts_desc'] = 'Dafay seet li nekk ci mod_page ak mod_book ngir gis iframe yu ñu dugal (Synthesia, YouTube, Articulate, Genially) te dafay jël adareesu bindu waxin bi ànd ak dugal bu nekk (dafay wut ci kaw ak ci suufu càkkaay bi). Dafa soxla jokkoo HTTPS bu génn jóge ci sarwóor bii ba ci dalub bindu waxin yi. <strong>Tëjul ci mbir mi</strong>; ubbi ko bu joxekatu bindu waxin bi dugal sarwóor bii ci limu ndigalam (misaal ak sartu Cloudflare bu tegu ci IP).';
$string['settings:rag_iframe_host_patterns'] = 'Melokaanu dalukaay yu iframe';
$string['settings:rag_iframe_host_patterns_desc'] = 'Benn wax bu wóor ci rëdd bu nekk, ñu koy dëppale ak jikkob <code>src</code> bu iframe. Càkkaay bu nekk bu dëppoo dañu koy jàppe ni dugal bu jokkoo bu ñu war a dëppale bindu waxinam te limal ko. Rëdd yi tàmbalee ak <code>#</code> ay wax lañu.';
$string['settings:rag_transcript_url_pattern'] = 'Melokaanu adareesu bindu waxin';
$string['settings:rag_transcript_url_pattern_desc'] = 'Wax bu wóor bu dëppoo ak adarees yu jokkalekaay yu bindu waxin. Ci iframe bu nekk bu ñu gis, limukat bi dafay tànn jokkalekaay bi gën a jege bu dëppoo (ci kawam walla ci suufam) te dafay dëppale ñaari yi. Bàyyi ko neen ngir tëj dëppaleb bindu waxin.';
$string['settings:performance_heading'] = 'Jëf';
$string['settings:performance_heading_desc'] = 'Dafay yor ñaata li nekk ci njàngale lañuy dugal ci ndigalu AI. Xayma yu ndaw dañu tekki tontu yu gaaw waaye mbir mu ndaw ngir AI.';
$string['settings:max_content_per_resource'] = 'Li nekk bi gën a réy ci buntu bu nekk (araf)';
$string['settings:max_content_per_resource_desc'] = 'Limu araf yu li nekk bi gën a réy ñu génne ci xët walla xaajub téere bu nekk. Xayma yu ndaw dañuy wàññi réyaayu ndigal bi te gaawal tontu yi.';
$string['settings:max_total_content'] = 'Li nekk lépp bi gën a réy (araf)';
$string['settings:max_total_content_desc'] = 'Limu araf yu li nekk ci njàngale lépp bi gën a réy ñu dugal ci ndigalu sistem. Xayma yu ndaw dañuy wàññi réyaayu ndigal bi te gaawal tontu yi.';
$string['settings:spend_guard_heading'] = 'Aaru njëg ak baaxalkat';
$string['settings:spend_guard_heading_desc'] = 'Teg dig yu njëgu LLM ci jamono bu nekk. Bu dig bi mat, [[tutorshort]] dafay taxaw ñaan yi walla mu soppiku ci joxekat bu gën a yomb ci sa cangu wutal. Xool <a href="{$a}">xëtu njëgu tokens</a> ngir anamu njëg bi tey ak digganteb baaxalkat bi.';
$string['settings:spend_cap_period'] = 'Jamonoy digu njëg';
$string['settings:spend_cap_period_desc'] = 'Ñaata yoon la digu njëg bi di dellu. Dafa dëppoo ak arminaat: bu weer di tàmbali ci fan bu 1, bu ayubés ci altine, bu bés ci xaaju guddi.';
$string['settings:spend_cap_site'] = 'Digu njëg ngir sit bi yépp (USD)';
$string['settings:spend_cap_site_desc'] = 'Dig bu boole ci USD ngir njàngale yépp ak mën-mën yépp ci jamono ji. <code>0</code> = amul dig. Dig yu mën-mën yu nekk ci suuf dañu gën a am solo su ñu leen teg.';
$string['settings:spend_cap_chat'] = 'Digu waxtaan (USD)';
$string['settings:spend_cap_chat_desc'] = 'Dig ngir waxtaan ak nattu yu jàngkat yi rekk. <code>0</code> = digu sit bi yépp lañuy jëfandikoo.';
$string['settings:spend_cap_voice'] = 'Digu baat (USD)';
$string['settings:spend_cap_voice_desc'] = 'Dig ngir baat (Realtime + TTS + STT). Baat mooy njëg bi gën a réy ci lu ëpp — tënk ko bu njëkk.';
$string['settings:spend_cap_rag'] = 'Digu RAG (USD)';
$string['settings:spend_cap_rag_desc'] = 'Dig ngir woote yu embedding yi ñu def bu ñuy limal njàngale yi.';
$string['settings:spend_cap_analytics'] = 'Digu seetlu (USD)';
$string['settings:spend_cap_analytics_desc'] = 'Dig ngir laaj yu Learning Radar yu yorekat yi.';
$string['settings:spend_failover_chain'] = 'Cangu wutal';
$string['settings:spend_failover_chain_desc'] = 'Bu dig bi mat, [[tutorshort]] dafay jéem joxekat yii ci toftale. Benn dugal ci rëdd bu nekk, ci melokaanu <code>capability:label</code>. Tur yi dañuy joxe dugal yi nekk ci Joxekat yu mengale (ngir <code>chat</code> / <code>analytics</code>) walla Joxekat yu baat (ngir <code>voice</code>). Rëdd yi tàmbalee ak <code>#</code> ay wax lañu. Misaal:<br><code>chat:claude-haiku<br>chat:ollama-local<br>voice:openai-prod<br>analytics:deepseek</code>';
$string['settings:failover_per_call_enabled'] = 'Soppiku ci wutal ci woote bu nekk (v5.5.0)';
$string['settings:failover_per_call_enabled_desc'] = 'Su ubbeeku, woote bu nekk bu waxtaan dafay lonk joxekat bu njëkk bi ci biir kaasu cangu wutal. Su jamono jeexoon ci woote walla njumteb 5xx am, [[tutorshort]] dafay soppiku ci dugal bi topp ci <strong>cangu wutal</strong> bi nekk ci kaw te dafay ubbi santaraal bu 15 simili ngir joxekat bi antuwul. Soppiku bu nekk dafay bind rëddu seetlu (<code>failover_fallthrough</code>); bu nga ko ubbi, xool Yoreb -> [[tutorshort]] -> Sàqu seetlu ngir wóor ne cang bi jëf na. Tëjul ci mbir mi; ubbi ko rekk bu ñu wóoral cang bi te sa kalimaan wóoral ne juboo yu jëfandikoob xibaar yu soxla ñungi am ngir joxekat bu nekk bu nekk ci cang bi.';
$string['settings:failover_timeout_chat'] = 'Wutal: jamonoy xaar bu waxtaan (simili)';
$string['settings:failover_timeout_chat_desc'] = 'Ñaata la wara xaar token bu njëkk bi jóge ci joxekatu waxtaan laata muy soppiku. Mbir mi 8 simili. Xayma yu ndaw dañuy jóge ci joxekat yu yeex gaaw, waaye dañuy indi yóotu nax yu bare ci ñaan yu yeex ci diir bu gàtt; xayma yu réy dañuy téye cang bi ci joxekat bu njëkk bi lu yàgg. Dañu koy jàpp rekk su <strong>soppiku ci wutal ci woote bu nekk</strong> ubbeeku.';
$string['settings:spend_notify_emails'] = 'Ñi jot yóotu njëg';
$string['settings:spend_notify_emails_desc'] = 'Adarees yu imeel yu xaajale ak firnde, ñu leen di xamal ci 80%, 95%, ak 100% bu dig bi. Bàyyi ko neen ngir xamal yorekat yu sit bi yépp.';
$string['settings:opt_cost_weight'] = 'Baaxalkat: diisaayu njëg';
$string['settings:opt_cost_weight_desc'] = 'Ñaata la baaxalkat bi di jàpp njëg bu muy toftal joxekat yi. 0.0 dafay bàyyi njëg bi, 1.0 dafay baaxal ci njëg rekk. Dañu koy natt ak diisaayu baax.';
$string['settings:opt_quality_weight'] = 'Baaxalkat: diisaayu baax';
$string['settings:opt_quality_weight_desc'] = 'Ñaata la baaxalkat bi di jàpp ngërëmu jàngkat bi (fàkkaayu natt yu baax) bu muy toftal joxekat yi. 0.0 dafay bàyyi baax bi.';
$string['settings:inactivity_reminder_enabled'] = 'Fàttaliku ci ñàkk jëf';
$string['settings:inactivity_reminder_enabled_desc'] = 'Dafay yónnee imeel ci ayubés ci jàngkat yi ubbiwul seen njàngale ci limu fan yi ñu teg.';
$string['settings:inactivity_threshold_days'] = 'Digu ñàkk jëf (fan)';
$string['settings:inactivity_threshold_days_desc'] = 'Ñaata fan yu ñàkk jëf laata imeelu fàttaliku di yónnee.';
$string['settings:voice_providers_heading'] = 'Joxekat yu baat (Realtime, TTS, STT)';
$string['settings:voice_providers_heading_desc'] = 'Defaral benn joxekatu API bu baat walla lu ëpp. Lii yépp du wéy ci joxekatu waxtaan bi nekk ci kaw ak joxekatu embedding bu RAG — baat am na limu joxekatam bopp, ndax léegi OpenAI ak xAI rekk lañuy joxe buntu Realtime yu tegu ci WebSocket, TTS, ak STT. Jëfandikoo lim yi nekk ci suuf ngir tànn ban joxekat bu ñu bind moo war a yore mën-mën bu nekk. Su ñu tànnul benn rëdd, jikko bu jëkk bu benn caabi lay jëf (caabiy API Realtime bi nekk ci kaw walla caabiy OpenAI bu mag). Sit bu jëfandikoo Together AI / Anthropic / DeepSeek / Gemini / Mistral ngir waxtaan war na defaral lu mucc benn rëdd fii ngir baat jëf.';
$string['settings:voice_active_realtime'] = 'Joxekatu Realtime bu jëf';
$string['settings:voice_active_realtime_desc'] = 'Ban joxekatu baat bu ñu defaral moo war a yore jamono yu ndawal baat bu Realtime.';
$string['settings:voice_active_tts'] = 'Joxekatu TTS bu jëf';
$string['settings:voice_active_tts_desc'] = 'Ban joxekatu baat bu ñu defaral moo war a jàng tontu yu AI ak baat bu kawe.';
$string['settings:voice_active_stt'] = 'Joxekatu STT bu jëf';
$string['settings:voice_active_stt_desc'] = 'Ban joxekat moo war a soppi waxinu jàngkat bi ci mbind. Bàyyi ko neen ngir sarwóoru Whisper bi nga yor sa bopp gën a am solo su ñu ko defaral ci suuf, ba noppi rëddu joxekat yu baat bu njëkk walla caabi bu jëkk.';
$string['settings:stt_selfhosted_enabled'] = 'Ubbi bindu waxin ci sa sarwóor bopp';
$string['settings:stt_selfhosted_enabled_desc'] = 'Dafay jëfandikoo sarwóoru Whisper bi nga yor sa bopp bu nekk ci suuf ni yoonu soppi waxin ci mbind ngir dugal baat ak Soapbox. Dafa soxla adareesu sarwóor ci suuf. Su tëjeeku, bindu waxin dafay dellu ci yoon bu ñu dalal (OpenAI Whisper) walla yoonu naawalekaay bi, doonte sax ñu teg adarees bi.';
$string['settings:stt_selfhosted_warm'] = 'Tàngal bu bindu Soapbox tàmbalee';
$string['settings:stt_selfhosted_warm_desc'] = 'Su ubbeeku, tàmbaleeb bindu Soapbox dafay yónnee ñaanu "tàngal" bu woyof (ci lu mën a am) ci sa sarwóoru bindu waxin bopp, ngir dalukaay bu wàññiku ba ci tus (misaal Cloud Run) mën a tàmbali bu jàngkat bi di bind ba tey — noonu, yeexu tàmbalee bu sedd dafay des nëbbu ci bindu waxin bi di jëf ci jamonoy yónnee. Amul jeexiital su ñu tegul adareesu sa sarwóor bopp ci kaw. Tëjul ci mbir mi.';
$string['settings:voice_tab_enabled'] = 'Ubbi tabu Baat';
$string['settings:voice_tab_enabled_desc'] = 'Dafay wone tabu Baat ci bàkku dox bu suuf. Su tëjeeku, jàngkat yi dañuy gis tab yu Waxtaan ak Not rekk. Mën-mën yu baat (jàngale waxtaan, jàngale wax) dañuy des ñu mën leen a jot ci tàmbaleeb waxtaan su ñu leen ubbi ci seen bopp.';
$string['settings:soapbox_heading'] = 'Soapbox';
$string['settings:soapbox_heading_desc'] = 'Jàngaleb wone ci gémmiñ: nan lañuy bind bindu yi te ci ban natt lañu leen di natt. Ubbi Soapbox ci njàngale bu nekk ak soppikukaayu Soapbox bi nekk ci wàllu Jàngale.';
$string['settings:soapbox_max_seconds'] = 'Guddaayu bindu Soapbox bi gën a gudd (simili)';
$string['settings:soapbox_max_seconds_desc'] = 'Dig bu mat sëkk ci kaw ngir guddaayu bindu ci liggéey bu mucc. Jàngalekat yi mën nañu teg diggante bu gën a gàtt. Mbir mi 720 (12 simili).';
$string['settings:soapbox_max_recordings'] = 'Bindu Soapbox yi gën a bare ci jàngkat ak liggéey bu nekk';
$string['settings:soapbox_max_recordings_desc'] = 'Dig bu mat sëkk ci kaw ngir limu bindu yu jàngkat mën def ci benn liggéey, te du xool tegub jéem ci liggéey bu nekk. Mbir mi 3.';
$string['settings:soapbox_retention_days'] = 'Jamonoy denc bindu Soapbox (fan)';
$string['settings:soapbox_retention_days_desc'] = 'Ñaata la bindu di des laata ñu koy far ci boppam; bindu waxin bi, natt bi, ak feedback bi dañuy des. Ñu koy tënk ci 1–28 fan. Bu ko gën a gàtt, moo gën ngir wàññi xibaar. Mbir mi 7.';
$string['settings:soapbox_video_quality'] = 'Baaxu wideyo bu Soapbox';
$string['settings:soapbox_video_quality_desc'] = 'Leerub ak fàkkaayu bit bu bindu bi. Lii mooy li gën a indi njëg ak yaatuwaayu jokkoo; waxkat bu ñu jël ci diggante gis nañu ko bu leer ci baax bu ndoxal sax. Baax bu suufe dafa mengoo ak jokkoo yu néew doole; baax bu kawe rekk bu leeral yu gis am solo.';
$string['settings:soapbox_storage_bucket'] = 'Bàntum dencukaayu Soapbox';
$string['settings:soapbox_storage_bucket_desc'] = 'Bàntum S3 ngir bindu yi. Mbir mi: bàntum denc bu ñu séddoo.';
$string['settings:soapbox_storage_region'] = 'Gox bu dencukaayu Soapbox';
$string['settings:soapbox_storage_region_desc'] = 'Goxu AWS bu bàntu bi, misaal us-east-1.';
$string['settings:soapbox_storage_prefix'] = 'Njëkk-turu caabiy dencukaayu Soapbox';
$string['settings:soapbox_storage_prefix_desc'] = 'Njëkk-turu caabi yi ci biir bàntu bi. Bindu yi ñungi leen denc ci suufu yoon wii, ngir sartu wérub dund mën leen a jublu.';
$string['settings:soapbox_storage_key'] = 'ID bu caabiy jot ci dencukaayu Soapbox';
$string['settings:soapbox_storage_key_desc'] = 'ID bu caabiy jot bu benn kilifa IAM bu ñu tënk ci PutObject/GetObject/DeleteObject ci njëkk-tur bi nekk ci kaw.';
$string['settings:soapbox_storage_secret'] = 'Caabiy jot bu kumpa ci dencukaayu Soapbox';
$string['settings:soapbox_storage_secret_desc'] = 'Caabiy jot bu kumpa bu dëppoo ak ID bu caabiy jot bi nekk ci kaw.';
$string['settings:survey_heading'] = 'Laajteb jàngkat yi';
$string['settings:survey_heading_desc'] = 'Defaral laajteb xam-xamu jàngkat bi nekk ci biir waxtaan. <a href="{$a}" class="btn btn-sm btn-outline-primary ml-2">Soppi laaj yu laajte bi &rarr;</a>';
$string['settings:survey_enabled'] = 'Ubbi laajte yi';
$string['settings:survey_enabled_desc'] = 'Su ubbeeku, dañuy woote jàngkat yi ngir ñu fees laajte ci seen xam-xam ak jàngalekatu AI bi.';
$string['settings:survey_trigger_messages'] = 'Wone ko bu bataaxal N jeex';
$string['settings:survey_trigger_messages_desc'] = 'Dafay wone woote laajte bi bu jàngkat bi yónnee limu bataaxal yii ci njàngale. Def 0 ngir ñu ko wone rekk su ñu ko tàmbalee ak loxo.';
