$string['settings:survey_frequency_desc'] = 'Ñaata yoon lañu mën a woote jàngkat ngir mu fees laajte bi ci njàngale bu nekk.';
$string['settings:rubric_heading'] = 'Nattu yu jàngale';
$string['settings:rubric_heading_desc'] = 'Defaral nattu yu joxe natt ngir jamono yu jàngale waxtaan ak wax. Ci muju jamonoy jàngale, jàngkat yi dañuy jot natt ak feedback bu AI defar. <a href="{$a}" class="btn btn-sm btn-outline-primary ml-2">Soppi nattu yi &rarr;</a>';
$string['settings:practice_scoring_enabled'] = 'Ubbi joxeb nattu jàngale';
$string['settings:practice_scoring_enabled_desc'] = 'Su ubbeeku, ci ginnaaw jamono yu jàngale waxtaan ak wax, jàngkat yi dañuy jot kart bu natt bu am seetluwu natt bu nekk ak feedback.';
$string['settings:usertesting_heading'] = 'Natteb yombaayu jëfandikoo';
$string['settings:usertesting_heading_desc'] = 'Natteb yombaayu jëfandikoo ci biir widget bi ak seetlu bu tegu ci liggéey. Jàngkat yi dañuy mate liggéey ci dimbalikat bi te nattal seen xam-xam. Jaar-jaar yi dañuy feeñ ci tablob seetlu.';
$string['settings:usertesting_enabled'] = 'Ubbi natteb yombaayu jëfandikoo';
$string['settings:usertesting_enabled_desc'] = 'Dafay wone jokkalekaay "Natteb yombaayu jëfandikoo" ci suufu widget bi. Su ubbeeku, jàngkat yi mën nañu jot liggéey yu natt.';
$string['settings:usertesting_external_url'] = 'Adareesu foroom bu biti (xeet C)';
$string['settings:usertesting_external_url_desc'] = 'Tànneef: adareesu benn foroom bu biti (misaal Google Forms walla Typeform). Jëfandikoo wuutukaay yii: {{userid}}, {{courseid}}, {{messages}}, {{session_minutes}}. Su ñu ko teg, tëb ci "Natteb yombaayu jëfandikoo" dafay ubbi adarees bii ak mbir mi ñu fees. Bàyyi ko neen ngir jëfandikoo tablob natt bi nekk ci biir widget bi rekk.';
$string['settings:footer_links_heading'] = 'Jokkalekaay yu suuf';
$string['settings:footer_links_heading_desc'] = 'Defaral jokkalekaay yi feeñ ci suufu dimbalikat bi: jokkalekaay bu tànneef ci limu njàngale ci suufu jokkalekaayu feedback, ak baat yu jokkalekaayu feedback ak tablo bi.';
$string['settings:footer_courses_text'] = 'Mbindu jokkalekaayu njàngale';
$string['settings:footer_courses_text_desc'] = 'Mbindu jokkalekaay bi feeñ ci suufu jokkalekaayu feedback. Bàyyi ko neen ngir nëbb jokkalekaay bi ba mat.';
$string['settings:footer_courses_url'] = 'Adareesu jokkalekaayu njàngale';
$string['settings:footer_courses_url_desc'] = 'Fu jokkalekaayu njàngale di jëm (dafay ubbeeku ci tab bu bees). Jokkalekaay bi dafay nëbbu su tool bii neen.';
$string['settings:feedback_link_label'] = 'Turu jokkalekaayu feedback';
$string['settings:feedback_link_label_desc'] = 'Dafay wuutu mbindu jokkalekaayu feedback bi nekk ci suuf, misaal "Yónnee xalaat ci [[tutorshort]] ci mbooloom IT". Bàyyi ko neen ngir jëfandikoo tur bu ñu tekki bu mbir mi "Feedback".';
$string['settings:feedback_panel_intro'] = 'Ubbiteb tablob feedback';
$string['settings:feedback_panel_intro_desc'] = 'Rëddu ubbite bi feeñ ci kaw tablob feedback. Dafay leeral fu xalaat yi jëm. Bàyyi ko neen ngir amul rëddu ubbite.';
$string['settings:quiz_provider'] = 'Joxekatu dimbalikatu nattu';
$string['settings:quiz_provider_desc'] = 'ID bu joxekat (misaal <code>claude</code> walla <code>openai</code>) ngir defar nattu. War na dëppoo ak benn rëdd ci Joxekat yu mengale. Bàyyi ko neen ngir jëfandikoo joxekatu waxtaan.';
$string['settings:quiz_model'] = 'Misaalu dimbalikatu nattu';
$string['settings:quiz_model_desc'] = 'Turu misaal ngir defar nattu, misaal <code>claude-haiku-4-5</code>. Tool bii ak joxekat bi ñaar yépp war nañu fees ngir wuutu bi jëf.';
$string['settings:branding_heading'] = 'Melokaanu tur';
$string['settings:branding_heading_desc'] = 'Defaral turu dimbalikat bi ak melokaanam.';
$string['settings:institution_short_name'] = 'Turu kalimaan bu gàtt';
