$string['settings:anomaly_digest_heading'] = 'Learning Radar — tënkub mbir yu ñu miinul';
$string['settings:anomaly_digest_heading_desc'] = 'Seet bu bés bu nekk bu mengale jamono yu dox ci natt yu bon, njëgu tokens, ak firndeb ndëgg. Bu benn firnde jàll dig bi ñu teg, tënk bi dañu koy yónnee ci yoon yi ñu defaral. Ngir rapoor yu ñu waxtaanal ci laaj bu nekk, jëfandikoo tablob Waxtaan bi nekk ci xëtu seetlu bu [[tutorshort]].';
$string['settings:anomaly_digest_enabled'] = 'Ubbi tënkub mbir yu ñu miinul';
