$string['settings:bench_min_quality_n'] = 'Plancher comparabilité (élément yu ñu note)';
$string['settings:bench_min_quality_n_desc'] = 'Limu élément yu ñu note bu gën a tuuti bi benn dox bu ñu deenc war a am ngir ñu mën ko comparer ak beneen dox. Dox yi nekk ci suuf plancher bi ñu leen denc te wone leen, ak label référence rekk, noonu benn dox smoke bu ñatti prompt mënul mukk weesu benn résultat bu 50 prompt. Baaral ko ci 0 ngir jëfandikoo bu defawu bi nekk ci code bi; plancher bu 0 day tas aar bii.';
$string['settings:embed_input_type_asymmetric'] = 'Ku yemoo laaj/dokimaa (ñu koy digal)';
$string['settings:embed_input_type_mode'] = 'Kiiraayu dugg embedding';
$string['settings:embed_input_type_mode_desc'] = 'Ci embeddings yu Voyage rekk. Voyage dafay wone mbind mi ci anam wu wute ndax laaj la walla dokimaa la. "Ku yemoo" dafay yónnee input_type=query bu ñuy jëfandikoo delloo, te input_type=document bu ñuy defar tëralin. Loolu la jaaykat bi bëgg, te moo gën a natt ci mbooloo mbind mii: jëfandikoo woneef dokimaa ci wetu laaj mi dafa yàq 30.8 poñ ci téeméer ci recall te ñàkk ci gépp géew guddaay laaj (2026-08-21, voyage-3.5, mbooloo mu mel ni liggéey bu dëggu). "Bérébu séddoo" dafay yónnee input_type=document ci ñaari wet yi; dafay delloo lu gën a bon ci natt, te am na rekk ni asuraas bu ay tëralin soppiku, ndaxte benn woneef rekk day tax ñu mën a soppi modeel laaj bi te du wara defaraat embeddings yu mbooloo mi. Tannal ku yemoo su dul ne yaa ngi ci diggu soppiku. Soppi lii soxlawul defaraat tëralin: woneef wetu laaj mi rekk moo soppiku. Lii DU boole modeel yu yemoo (defar tëralin ak modeel Voyage bu gën a mag ci bi ngay laaje) — loolu benn xeltu bu wute la bu ñu mënul woon a delloo ñaari yoon ci mbooloo mii, te tëralinu modeel laaj bi moo koy yóbbe, du tëralin bii.';
$string['settings:embed_input_type_shared'] = 'Bérébu séddoo (asuraasu soppiku; delloo bu gën a bon)';
$string['settings:embed_migration_heading'] = 'Migration modèle embedding';
$string['settings:embed_migration_heading_desc'] = 'Soppi modèle embedding walla yaatuwaayam day tas vecteur yépp yu ñu deenc: récupérateur bi day nangu note benn laaj ak chunk yu jóge ci beneen espace embedding, noonu benn kurs du récupérer dara te du récupérer lu bon. Paramètre yii dañuy waxtaan modèle bi nga jëm CI. Ba noppi ñu day embed kurs yi benn-benn jóge ci xët index RAG bi, di bind vecteur yu bees yi ci wetu yu yàgg yi, te paramètre yu jëm yi ci kaw dañuy sax di jox récupération ba nga leen soppi sa bopp.';
$string['settings:embed_migration_provider_inherit'] = 'Jëfandikoo prestataire bi configuré ci kaw';
$string['settings:embed_migration_target_apikey'] = 'Caabi API bu prestataire cible bi';
$string['settings:embed_migration_target_apikey_desc'] = 'Ñu ko soxla rekk su prestataire cible bi wuute ak bi configuré ci kaw. Neen mooy jëfandikoo caabi embedding bi am.';
$string['settings:embed_migration_target_dimensions'] = 'Yaatuwaay embedding cible';
$string['settings:embed_migration_target_dimensions_desc'] = 'Yaatuwaay vecteur bi ñu war a laaj ci biir migration bi. 0 mooy yaatuwaay bu ndeyu modèle bi. Voyage nangu na 256, 512, 1024 ak 2048; yaatuwaay bu modèle bi joxeul ñu koy génn ci laaj bi te du ko yónni, ndax loolu day jox la yaatuwaay bu ndey te du bi nga laaj.';
$string['settings:embed_migration_target_model'] = 'Modèle embedding cible';
$string['settings:embed_migration_target_model_desc'] = 'Tur modèle bi ñu war a embed ak moom ci biir migration bi, misaal <code>voyage-4-large</code>. Neen mooy amul migration bu configuré te xët index RAG bi du joxe benn tann.';
$string['settings:embed_migration_target_provider'] = 'Prestataire embedding cible';
$string['settings:embed_migration_target_provider_desc'] = 'Baaral ko neen ngir migre ci biir prestataire bi ñu configuré ba noppi ci kaw.';
$string['settings:rerank_min_query_chars'] = 'Rerank: gudday laaj bu gën a tuuti';
$string['settings:rerank_min_query_chars_desc'] = 'Génn re-ranker bi ngir laaj yu gudd ni araf yii walla yu gën a gàtt. Laaj yu gàtt ay mot-clé rekk te re-ranker bi yokkul lu bare ci kaw similarité cosinus ci ñaar walla ñatti baat. Ñu ko mesure ci ensemble fixture RAG: tëkkale ci 50 jël na 67,7% recall ci kanam 67,2% ngir bi ubbi bees, ci lu tollu ci benn ñatteel njëg bi. Defal ko 0 ngir rerank laaj yépp. Rerank yi ñu génn ñu leen bind ci log bataaxal ni "[Rerank skipped: short_query]" ngir nga mën a wóorlu ne barab bi dox na.';
$string['settings:spend_export_key'] = 'Caabi export njëg';
$string['settings:spend_export_key_desc'] = 'Caabi Bearer ngir endpoint export njëg AI bu weer bi ci <code>/local/ai_course_assistant/spend_export.php</code>, bi dashboard njëg bi di jël benn yoon ci weer. Baaral ko neen ngir tëj endpoint bi — day tontu 404 ci kenn-kenn laaj. Caabi bi ñu koy nangu REKK ci benn header <code>Authorization: Bearer</code>, du mukk ci URL bi. Sosal benn valeur aléatoire bu gudd; ku ko yor mën na jàng njëg AI bu site bi yépp. Kenn-kenn export bu antu ñu koy bind ci log audit bu plugin bi.';
